			SpecialAttackWeapon.ELDER_MAUL, 40, 100, 100, false, false, true, false);

		assertEquals(40, result.getTotalMaximumHit());
		assertEquals(CombatPrediction.hitChance(125, 100), result.getHitChance(), EPSILON);
