package com.combatinsight.calculation;

import java.util.Locale;

/** Basic-attack distributions for the first supported multi-hit weapons. */
public enum MultiHitWeapon
{
	SCYTHE_OF_VITUR,
	DUAL_MACUAHUITL,
	TORAGS_HAMMERS,
	SULPHUR_BLADES,
	DARK_BOW;

	public static MultiHitWeapon forWeapon(String weaponName)
	{
		if (weaponName == null)
		{
			return null;
		}

		String weapon = weaponName.toLowerCase(Locale.ROOT);
		if (weapon.contains("scythe of vitur"))
		{
			return SCYTHE_OF_VITUR;
		}
		if (weapon.contains("dual macuahuitl"))
		{
			return DUAL_MACUAHUITL;
		}
		if (weapon.contains("torag's hammers"))
		{
			return TORAGS_HAMMERS;
		}
		if (weapon.contains("sulphur blades"))
		{
			return SULPHUR_BLADES;
		}
		if (weapon.contains("dark bow"))
		{
			return DARK_BOW;
		}
		return null;
	}

	public MultiHitResult calculate(
		int minimumHit,
		int maximumHit,
		int flatArmour,
		double hitChance,
		int targetSize,
		int attackSpeedTicks,
		boolean guaranteedMaximum,
		boolean fullBloodMoonSet)
	{
		int maximum = Math.max(0, maximumHit);
		int minimum = Math.max(0, Math.min(minimumHit, maximum));
		double chance = Math.max(0.0, Math.min(1.0, hitChance));
		int[] rollMaximums = rollMaximums(maximum, targetSize);
		if (maximum == 0)
		{
			return new MultiHitResult(new int[rollMaximums.length], 0.0, 0.0, attackSpeedTicks);
		}

		int[] transformedMaximums = new int[rollMaximums.length];
		double[] averageHits = new double[rollMaximums.length];

		for (int i = 0; i < rollMaximums.length; i++)
		{
			int rollMaximum = Math.max(minimum, rollMaximums[i]);
			transformedMaximums[i] = DamageRoll.maximumSuccessfulHit(rollMaximum, flatArmour);
			averageHits[i] = DamageRoll.averageSuccessfulHit(minimum, rollMaximum, flatArmour);
		}

		double expectedDamage;
		double successfulAttackChance;
		if (guaranteedMaximum)
		{
			expectedDamage = sum(transformedMaximums);
			successfulAttackChance = 1.0;
			chance = 1.0;
		}
		else
		{
			switch (this)
			{
				case DUAL_MACUAHUITL:
					expectedDamage = chance * averageHits[0]
						+ chance * chance * averageHits[1];
					successfulAttackChance = chance;
					break;
				case SCYTHE_OF_VITUR:
					expectedDamage = chance * sum(averageHits);
					successfulAttackChance = 1.0 - Math.pow(1.0 - chance, averageHits.length);
					break;
				case TORAGS_HAMMERS:
				case SULPHUR_BLADES:
				case DARK_BOW:
				default:
					expectedDamage = chance * sum(averageHits);
					successfulAttackChance = 1.0 - Math.pow(1.0 - chance, averageHits.length);
					break;
			}
		}

		double expectedSpeed = Math.max(1, attackSpeedTicks);
		if (this == DUAL_MACUAHUITL && fullBloodMoonSet)
		{
			// Each accurate hitsplat has a one-third chance to shorten the next
			// attack by one tick. The second hit can only be accurate after the first.
			double speedupChance = chance / 3.0 + 2.0 * chance * chance / 9.0;
			expectedSpeed = Math.max(1.0, expectedSpeed - speedupChance);
		}

		return new MultiHitResult(
			transformedMaximums,
			expectedDamage,
			successfulAttackChance,
			expectedSpeed);
	}

	private int[] rollMaximums(int maximumHit, int targetSize)
	{
		switch (this)
		{
			case SCYTHE_OF_VITUR:
				int hitCount = Math.min(3, Math.max(1, targetSize));
				int[] scytheHits = new int[hitCount];
				for (int i = 0; i < hitCount; i++)
				{
					scytheHits[i] = maximumHit / (1 << i);
				}
				return scytheHits;
			case DUAL_MACUAHUITL:
			case TORAGS_HAMMERS:
			case SULPHUR_BLADES:
				int firstMaximum = maximumHit / 2;
				return new int[]{firstMaximum, maximumHit - firstMaximum};
			case DARK_BOW:
			default:
				return new int[]{maximumHit, maximumHit};
		}
	}

	private static int sum(int[] values)
	{
		int total = 0;
		for (int value : values)
		{
			total += value;
		}
		return total;
	}

	private static double sum(double[] values)
	{
		double total = 0.0;
		for (double value : values)
		{
			total += value;
		}
		return total;
	}
}

package com.combatinsight.calculation;

/**
 * Core combat formulas kept independent from RuneLite UI and client code.
 *
 * This is deliberately a readable baseline. Equipment-specific effects, NPC
 * modifiers, multi-hit distributions, and special attacks are layered around
 * this model rather than embedded in the panel.
 */
public final class OsrsCombatCalculator
{
	private static final double SECONDS_PER_TICK = 0.6;
	private static final int GLOBAL_DAMAGE_CAP = 200;

	private OsrsCombatCalculator()
	{
	}

	public static CombatResult calculate(CombatState state)
	{
		if (state == null || state.getTarget() == null)
		{
			throw new IllegalArgumentException("A target is required");
		}

		int effectiveAttack;
		int attackRoll;
		int defenceRoll;
		int maxHit;

		switch (state.getCombatStyle())
		{
			case MELEE:
				effectiveAttack = effectiveLevel(
					state.getStats().getAttack(),
					state.getBoosts().getAttack(),
					state.getPrayers().getAttackMultiplier(),
					state.getAttackStyle().getAttackStyleBonus());
				attackRoll = effectiveAttack * (state.getGear().getMeleeAttack() + 64);
				defenceRoll = state.getTarget().getDefenceLevel() * (state.getTarget().getMeleeDefence() + 64);
				int effectiveStrength = effectiveLevel(
					state.getStats().getStrength(),
					state.getBoosts().getStrength(),
					state.getPrayers().getStrengthMultiplier(),
					state.getAttackStyle().getStrengthStyleBonus());
				maxHit = (int) Math.floor(0.5
					+ effectiveStrength * (state.getGear().getMeleeStrength() + 64) / 640.0);
				break;

			case RANGED:
				effectiveAttack = effectiveLevel(
					state.getStats().getRanged(),
					state.getBoosts().getRanged(),
					state.getPrayers().getRangedMultiplier(),
					state.getAttackStyle().getAttackStyleBonus());
				attackRoll = effectiveAttack * (state.getGear().getRangedAttack() + 64);
				defenceRoll = state.getTarget().getDefenceLevel() * (state.getTarget().getRangedDefence() + 64);
				maxHit = (int) Math.floor(0.5
					+ effectiveAttack * (state.getGear().getRangedStrength() + 64) / 640.0);
				break;

			case MAGIC:
			default:
				effectiveAttack = effectiveLevel(
					state.getStats().getMagic(),
					state.getBoosts().getMagic(),
					1.0,
					state.getAttackStyle().getAttackStyleBonus());
				attackRoll = effectiveAttack * (state.getGear().getMagicAttack() + 64);
				defenceRoll = state.getTarget().getMagicDefence() * (state.getTarget().getDefenceLevel() + 64);
				maxHit = (int) Math.floor(state.getMagicBaseMaxHit()
					* (1.0 + (state.getGear().getMagicDamagePercent()
						+ state.getPrayers().getMagicDamagePercent()) / 100.0));
				break;
		}

		maxHit = Math.min(GLOBAL_DAMAGE_CAP, Math.max(0, maxHit));

		double accuracy = hitChance(attackRoll, defenceRoll);
		double averageHit = maxHit * 0.5 * accuracy;
		double damagePerSecond = averageHit / (state.getGear().getAttackSpeedTicks() * SECONDS_PER_TICK);

		return new CombatResult(effectiveAttack, attackRoll, defenceRoll, maxHit, accuracy, averageHit, damagePerSecond);
	}

	private static int effectiveLevel(int level, int boost, double prayerMultiplier, int styleBonus)
	{
		return (int) Math.floor((level + boost) * prayerMultiplier) + styleBonus + 8;
	}

	private static double hitChance(int attackRoll, int defenceRoll)
	{
		if (attackRoll > defenceRoll)
		{
			return 1.0 - (double) (defenceRoll + 2) / (2.0 * (attackRoll + 1));
		}

		return (double) attackRoll / (2.0 * (defenceRoll + 1));
	}
}

package com.combatinsight.calculation;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/** Immutable combat data for one NPC ID. */
public final class TargetProfile
{
	private final int id;
	private final int defenceLevel;
	private final int magicLevel;
	private final int hitpoints;
	private final int offensiveMagic;
	private final int size;
	private final int flatArmour;
	private final int stabDefence;
	private final int slashDefence;
	private final int crushDefence;
	private final int magicDefence;
	private final int lightRangedDefence;
	private final int standardRangedDefence;
	private final int heavyRangedDefence;
	private final String weaknessElement;
	private final int weaknessSeverity;
	private final boolean slayerMonster;
	private final Set<String> attributes;
	private final boolean ambiguous;

	public TargetProfile(
		int id,
		int defenceLevel,
		int magicLevel,
		int hitpoints,
		int offensiveMagic,
		int size,
		int flatArmour,
		int stabDefence,
		int slashDefence,
		int crushDefence,
		int magicDefence,
		int lightRangedDefence,
		int standardRangedDefence,
		int heavyRangedDefence,
		String weaknessElement,
		int weaknessSeverity,
		boolean slayerMonster,
		Set<String> attributes,
		boolean ambiguous)
	{
		this.id = id;
		this.defenceLevel = defenceLevel;
		this.magicLevel = magicLevel;
		this.hitpoints = hitpoints;
		this.offensiveMagic = offensiveMagic;
		this.size = size;
		this.flatArmour = flatArmour;
		this.stabDefence = stabDefence;
		this.slashDefence = slashDefence;
		this.crushDefence = crushDefence;
		this.magicDefence = magicDefence;
		this.lightRangedDefence = lightRangedDefence;
		this.standardRangedDefence = standardRangedDefence;
		this.heavyRangedDefence = heavyRangedDefence;
		this.weaknessElement = weaknessElement == null ? "" : weaknessElement;
		this.weaknessSeverity = Math.max(0, weaknessSeverity);
		this.slayerMonster = slayerMonster;
		this.attributes = Collections.unmodifiableSet(new HashSet<>(attributes));
		this.ambiguous = ambiguous;
	}

	public int getId()
	{
		return id;
	}

	public int getDefenceLevel()
	{
		return defenceLevel;
	}

	public int getMagicLevel()
	{
		return magicLevel;
	}

	public int getHitpoints()
	{
		return hitpoints;
	}

	public int getOffensiveMagic()
	{
		return offensiveMagic;
	}

	public int getSize()
	{
		return size;
	}

	public int getFlatArmour()
	{
		return flatArmour;
	}

	public String getWeaknessElement()
	{
		return weaknessElement;
	}

	public int getWeaknessSeverity()
	{
		return weaknessSeverity;
	}

	public boolean isSlayerMonster()
	{
		return slayerMonster;
	}

	public boolean hasAttribute(String attribute)
	{
		return attributes.contains(attribute);
	}

	public boolean isAmbiguous()
	{
		return ambiguous;
	}

	/** Returns a derived live profile without mutating the bundled target data. */
	public TargetProfile withCombatStats(int liveDefenceLevel, int liveMagicLevel, int liveMagicDefence)
	{
		return new TargetProfile(
			id,
			Math.max(0, liveDefenceLevel),
			Math.max(0, liveMagicLevel),
			hitpoints,
			offensiveMagic,
			size,
			flatArmour,
			stabDefence,
			slashDefence,
			crushDefence,
			liveMagicDefence,
			lightRangedDefence,
			standardRangedDefence,
			heavyRangedDefence,
			weaknessElement,
			weaknessSeverity,
			slayerMonster,
			attributes,
			ambiguous);
	}

	public int defenceBonus(AttackType attackType)
	{
		switch (attackType)
		{
			case STAB:
				return stabDefence;
			case SLASH:
				return slashDefence;
			case CRUSH:
				return crushDefence;
			case MAGIC:
				return magicDefence;
			case RANGED_LIGHT:
				return lightRangedDefence;
			case RANGED_HEAVY:
				return heavyRangedDefence;
			case RANGED_MIXED:
				return (lightRangedDefence + standardRangedDefence + heavyRangedDefence) / 3;
			case RANGED_STANDARD:
			default:
				return standardRangedDefence;
		}
	}

	/** Derived raid profile; bundled records always retain unscaled base values. */
	public TargetProfile withRaidStats(int defence, int magic, int maximumHitpoints)
	{
		return new TargetProfile(id, defence, magic, maximumHitpoints, offensiveMagic,
			size, flatArmour, stabDefence, slashDefence, crushDefence, magicDefence,
			lightRangedDefence, standardRangedDefence, heavyRangedDefence,
			weaknessElement, weaknessSeverity, slayerMonster, attributes, ambiguous);
	}
}

