		11709, 11712, 9118);

	private static final Set<Integer> KEPHRI_OVERLORDS = ids(11724, 11725, 11726);

	private static final Set<Integer> MELEE_IMMUNE = ids(
		494, 7533, 7706, 7708,
		12214, 12215, 12219,
		2042, 2043, 2044);

	private static final Set<Integer> NON_SALAMANDER_MELEE_IMMUNE = ids(
		3169, 3170, 3171, 3172, 3173, 3174, 3175, 3176, 3177,
		3178, 3179, 3180, 3181, 3182, 3183, 7037);

	private static final Set<Integer> ZULRAH = ids(2042, 2043, 2044);
	private static final Set<Integer> VESPULA = ids(7530, 7531, 7532);
	private static final Set<Integer> GUARDIANS = ids(7569, 7571, 7570, 7572);

	private static final Set<Integer> RANGED_IMMUNE = ids(
		7540, 7543, 7544, 7545,
		7851, 7854, 7855, 7882, 7883, 7886, 7887, 7888, 7889,
		7568,
		2463, 2465, 2467, 2464, 2466, 2468,
		2137, 2138, 2139, 2140, 2141, 2142);

	private static final Set<Integer> MAGIC_IMMUNE = ids(
		7851, 7854, 7855, 7882, 7883, 7886, 7887, 7888, 7889,
		2463, 2465, 2467, 2464, 2466, 2468,
		2137, 2138, 2139, 2140, 2141, 2142);

	private TargetMechanics()
	{
	}

	static boolean isInTombsOfAmascut(int npcId)
	{
		return TOMBS_OF_AMASCUT.contains(npcId);
	}

	static boolean magicUsesDefenceLevel(int npcId)
	{
		return MAGIC_USES_DEFENCE_LEVEL.contains(npcId);
	}

	static boolean scalesWithToaInvocation(int npcId)
	{
		return TOMBS_OF_AMASCUT.contains(npcId) && !KEPHRI_OVERLORDS.contains(npcId);
	}

	/** Scurrius's summoned rats are always hit and always receive the max damage roll. */
	static boolean isGuaranteedMaxHitTarget(int npcId)
	{
		return npcId == SCURRIUS_SPAWNED_RAT;
	}

	static boolean isImmune(int npcId, AttackType attackType)
	{
		int nyloStyle = nylocasStyle(npcId);
		if (nyloStyle != 0)
		{
			return nyloStyle == 1 ? !attackType.isMelee()
				: nyloStyle == 2 ? !attackType.isRanged() : attackType != AttackType.MAGIC;
		}
		if (attackType.isMelee())
		{
			return MELEE_IMMUNE.contains(npcId);
		}
		if (attackType.isRanged())
		{
			return RANGED_IMMUNE.contains(npcId);
		}
		return attackType == AttackType.MAGIC && MAGIC_IMMUNE.contains(npcId);
	}

	/** 1 = melee, 2 = ranged, 3 = magic; IDs track each live colour change. */
	private static int nylocasStyle(int id)
	{
		if (id >= 8342 && id <= 8353) return (id - 8342) % 3 + 1;
		if (id >= 10774 && id <= 10785) return (id - 10774) % 3 + 1;
		if (id >= 10791 && id <= 10802) return (id - 10791) % 3 + 1;
		if (id >= 8381 && id <= 8383) return id - 8380;
		if (id >= 10841 && id <= 10843) return id - 10840;
		if (id >= 10858 && id <= 10860) return id - 10857;
		switch (id)
		{
			case 8355: case 10787: case 10804: case 10808: return 1;
			case 8357: case 10789: case 10806: case 10810: return 2;
			case 8356: case 10788: case 10805: case 10809: return 3;
			default: return 0;
		}
	}

	static boolean isNonSalamanderMeleeImmune(int npcId)
	{
		return NON_SALAMANDER_MELEE_IMMUNE.contains(npcId);
	}

	static boolean isZulrah(int npcId)
	{
		return ZULRAH.contains(npcId);
	}

	static boolean isVespula(int npcId)
	{
		return VESPULA.contains(npcId);
	}

	static boolean isGuardian(int npcId)
	{
		return GUARDIANS.contains(npcId);
	}

	private static Set<Integer> ids(Integer... values)
	{
		return new HashSet<>(Arrays.asList(values));
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.WeaponCategory;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/** Resolves equipped weapon item IDs to their combat-interface category. */
final class WeaponCategoryDatabase
{
	private static final String RESOURCE = "/com/combatinsight/data/weapon-categories.tsv";
	private static final Map<Integer, WeaponCategory> CATEGORIES = load();

	private WeaponCategoryDatabase()
	{
	}

	static WeaponCategory find(int itemId)
	{
		return CATEGORIES.getOrDefault(itemId, WeaponCategory.UNKNOWN);
	}

	private static Map<Integer, WeaponCategory> load()
	{
		InputStream stream = WeaponCategoryDatabase.class.getResourceAsStream(RESOURCE);
		if (stream == null)
		{
			throw new IllegalStateException("Missing weapon category resource " + RESOURCE);
		}

		Map<Integer, WeaponCategory> categories = new HashMap<>();
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}
				String[] fields = line.split("\\t", -1);
				if (fields.length != 2)
				{
					throw new IllegalStateException("Invalid weapon category row: " + line);
				}
				categories.put(
					Integer.parseInt(fields[0]),
					WeaponCategory.fromDataName(fields[1]));
			}
		}
		catch (IOException | NumberFormatException ex)
		{
			throw new IllegalStateException("Could not load bundled weapon categories", ex);
		}
		return Collections.unmodifiableMap(categories);
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.SpecialAttackWeapon;
import net.runelite.api.NPC;

/** Detects local special use and binds its next hitsplat to a live target. */
public final class SpecialAttackTracker
{
	private static final int PENDING_TIMEOUT_TICKS = 5;

	private final TargetEffectTracker targetEffects = new TargetEffectTracker();
	private int previousEnergy = -1;
	private PendingSpecial pendingSpecial;
	private RaidScaling raidScaling = RaidScaling.DEFAULT;

	public void setRaidScaling(RaidScaling next)
	{
		if (!raidScaling.equals(next))
		{
			pendingSpecial = null;
			raidScaling = next;
			targetEffects.setRaidScaling(next);
		}
	}

	public void resetEnergy(int specialEnergy)
	{
		previousEnergy = specialEnergy;
		pendingSpecial = null;
	}

	public boolean onEnergyChanged(
		int specialEnergy,
		SpecialAttackWeapon weapon,
		NPC target,
		int gameTick)
	{
		if (previousEnergy < 0 || specialEnergy >= previousEnergy)
		{
			previousEnergy = specialEnergy;
			return false;
		}

		previousEnergy = specialEnergy;
		pendingSpecial = weapon != null && weapon.hasTrackedTargetEffect()
			? new PendingSpecial(weapon, target, gameTick + PENDING_TIMEOUT_TICKS)
			: null;
		return pendingSpecial != null;
	}

	public boolean onHitsplat(NPC target, int displayedDamage, int gameTick)
	{
		return onHitsplat(target, displayedDamage, displayedDamage > 0, gameTick);
	}

	public boolean onHitsplat(
		NPC target,
		int displayedDamage,
		boolean accurate,
		int gameTick)
	{
		if (pendingSpecial == null || target == null)
		{
			return false;
		}
		if (gameTick > pendingSpecial.expiresAtTick)
		{
			pendingSpecial = null;
			return false;
		}
		if (pendingSpecial.target != null && pendingSpecial.target != target)
		{
			return false;
		}

		SpecialAttackWeapon weapon = pendingSpecial.weapon;
		targetEffects.record(weapon, target, displayedDamage, accurate, gameTick);
		pendingSpecial.remainingHits--;
		if (pendingSpecial.remainingHits <= 0)
		{
			pendingSpecial = null;
		}
		return true;
	}

	public void onGameTick(int gameTick)
	{
		if (pendingSpecial != null && gameTick > pendingSpecial.expiresAtTick)
		{
			pendingSpecial = null;
		}
	}

	public TargetEffectSnapshot getTargetEffects(NPC target, int gameTick)
	{
		return targetEffects.snapshot(target, gameTick);
	}

	public void remove(NPC target)
	{
		if (pendingSpecial != null && pendingSpecial.target == target)
		{
			pendingSpecial = null;
		}
		targetEffects.remove(target);
	}

	public void clear()
	{
		previousEnergy = -1;
		pendingSpecial = null;
		targetEffects.clear();
	}

	private static final class PendingSpecial
	{
		private final SpecialAttackWeapon weapon;
		private final NPC target;
		private final int expiresAtTick;
		private int remainingHits;

		private PendingSpecial(SpecialAttackWeapon weapon, NPC target, int expiresAtTick)
		{
			this.weapon = weapon;
			this.target = target;
			this.expiresAtTick = expiresAtTick;
			this.remainingHits = weapon.getEffectHitCount();
		}
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.TargetProfile;
import java.util.Locale;

/** Read-only live target levels derived from locally observed special attacks. */
public final class TargetEffectSnapshot
{
	private static final TargetEffectSnapshot EMPTY = new TargetEffectSnapshot(
		-1, 0, 0, 0, 0, 0, 0, false, false, false, false);

	private final int targetId;
	private final int baseDefence;
	private final int currentDefence;
	private final int baseMagic;
	private final int currentMagic;
	private final int baseMagicDefence;
	private final int currentMagicDefence;
	private final boolean trackedEffect;
	private final boolean estimatedDefenceRecovery;
	private final boolean estimatedMagicRecovery;
	private final boolean tektonDefenceSpecialAttempted;

	TargetEffectSnapshot(
		int targetId,
		int baseDefence,
		int currentDefence,
		int baseMagic,
		int currentMagic,
		int baseMagicDefence,
		int currentMagicDefence,
		boolean trackedEffect,
		boolean estimatedDefenceRecovery,
		boolean estimatedMagicRecovery,
		boolean tektonDefenceSpecialAttempted)
	{
		this.targetId = targetId;
		this.baseDefence = Math.max(0, baseDefence);
		this.currentDefence = Math.max(0, currentDefence);
		this.baseMagic = Math.max(0, baseMagic);
		this.currentMagic = Math.max(0, currentMagic);
		this.baseMagicDefence = baseMagicDefence;
		this.currentMagicDefence = currentMagicDefence;
		this.trackedEffect = trackedEffect;
		this.estimatedDefenceRecovery = estimatedDefenceRecovery;
		this.estimatedMagicRecovery = estimatedMagicRecovery;
		this.tektonDefenceSpecialAttempted = tektonDefenceSpecialAttempted;
	}

	public static TargetEffectSnapshot empty()
	{
		return EMPTY;
	}

	static TargetEffectSnapshot unmodified(TargetProfile target)
	{
		if (target == null || target.isAmbiguous())
		{
			return EMPTY;
		}
		int magicDefence = target.defenceBonus(com.combatinsight.calculation.AttackType.MAGIC);
		return new TargetEffectSnapshot(
			target.getId(),
			target.getDefenceLevel(),
			target.getDefenceLevel(),
			target.getMagicLevel(),
			target.getMagicLevel(),
			magicDefence,
			magicDefence,
			false,
			false,
			false,
			false);
	}

	public boolean hasTargetStats()
	{
		return targetId >= 0;
	}

	public boolean appliesTo(int npcId)
	{
		return hasTargetStats() && targetId == npcId;
	}

	public TargetProfile applyTo(TargetProfile target)
	{
		if (target == null || !appliesTo(target.getId()))
		{
			return target;
		}
		return target.withCombatStats(currentDefence, currentMagic, currentMagicDefence);
	}

	public int getBaseDefence()
	{
		return baseDefence;
	}

	public int getCurrentDefence()
	{
		return currentDefence;
	}

	public int getBaseMagic()
	{
		return baseMagic;
	}

	public int getCurrentMagic()
	{
		return currentMagic;
	}

	public int getBaseMagicDefence()
	{
		return baseMagicDefence;
	}

	public int getCurrentMagicDefence()
	{
		return currentMagicDefence;
	}

	public boolean hasTrackedEffect()
	{
		return trackedEffect;
	}

	public boolean hasTrackedDefence()
	{
		return currentDefence != baseDefence;
	}

	public boolean hasTrackedMagic()
	{
		return currentMagic != baseMagic;
	}

	public boolean hasTrackedMagicDefence()
	{
		return currentMagicDefence != baseMagicDefence;
	}

	/**
	 * Before any Magic-related drain, the infobox introduces the target using
	 * its Magic Defence bonus. A tracked Magic-level drain takes priority only
	 * when no Magic Defence bonus reduction is active.
	 */
	public boolean displaysMagicDefenceBonus()
	{
		return hasTrackedMagicDefence() || !hasTrackedMagic();
	}

	public boolean isEstimatedRecovery()
	{
		return estimatedDefenceRecovery || estimatedMagicRecovery;
	}

	public boolean isTektonDefenceSpecialAttempted()
	{
		return tektonDefenceSpecialAttempted;
	}

	public String getDefenceText()
	{
		if (!hasTargetStats())
		{
			return "Unavailable";
		}
		String suffix = hasTrackedDefence() ? estimatedDefenceRecovery ? " est." : " tracked" : "";
		return String.format(Locale.ROOT, "%,d / %,d%s", currentDefence, baseDefence, suffix);
	}

	public String getMagicText()
	{
		if (!hasTargetStats())
		{
			return "Unavailable";
		}
		String suffix = hasTrackedMagic() ? estimatedMagicRecovery ? " est." : " tracked" : "";
		return String.format(Locale.ROOT, "%,d / %,d%s", currentMagic, baseMagic, suffix);
	}

	public String getMagicDefenceText()
	{
		if (!hasTargetStats())
		{
			return "Unavailable";
		}
		String suffix = hasTrackedMagicDefence() ? " tracked" : "";
		return String.format(Locale.ROOT, "%+,d / %+,d%s",
			currentMagicDefence, baseMagicDefence, suffix);
	}
}

package com.combatinsight.live;

import java.util.Locale;

/**
 * Selects the ammunition the equipped weapon can actually fire.
 *
 * Dizana's quiver can provide a second arrow or bolt stack. The ordinary ammo
 * slot wins when it contains compatible ammunition; otherwise the compatible
 * quiver stack is used. An incompatible stack, such as bolts with a dark bow,
 * must never contribute stats merely because it is equipped.
 */
final class AmmunitionRules
{
	enum Source
	{
		NONE,
		WORN,
		QUIVER
	}

	private AmmunitionRules()
	{
	}

	static boolean wornAmmoContributes(String weaponName)
	{
		return weaponName == null
			|| !weaponName.toLowerCase(Locale.ROOT).contains("blowpipe");
	}

	static Source selectSource(
		String weaponName,
		String wornAmmoName,
		String quiverAmmoName)
	{
		if (isCompatible(weaponName, wornAmmoName))
		{
			return Source.WORN;
		}
		if (isCompatible(weaponName, quiverAmmoName))
		{
			return Source.QUIVER;
		}
		return Source.NONE;
	}

	static boolean sunfireBonusApplies(String weaponName, String ammoName)
	{
		String weapon = normalize(weaponName);
		String ammo = normalize(ammoName);
		return isCompatible(weapon, ammo)
			&& (isArrow(ammo) || isBolt(ammo))
			&& !weapon.contains("venator bow");
	}

	private static boolean isCompatible(String weaponName, String ammoName)
	{
		String weapon = normalize(weaponName);
		String ammo = normalize(ammoName);
		if (weapon.isEmpty() || ammo.isEmpty())
		{
			return false;
		}
		if (weapon.contains("blowpipe") || isSelfPoweredBow(weapon))
		{
			return false;
		}
		if (weapon.contains("crossbow"))
		{
			return isBolt(ammo);
		}
		if (weapon.contains("ballista"))
		{
			return ammo.contains("javelin");
		}
		if (weapon.contains("atlatl"))
		{
			return ammo.contains("atlatl dart");
		}
		if (weapon.contains("bow"))
		{
			return isArrow(ammo);
		}
		return false;
	}

	private static boolean isSelfPoweredBow(String weapon)
	{
		return weapon.contains("crystal bow")
			|| weapon.contains("bow of faerdhinen")
			|| weapon.contains("craw's bow")
			|| weapon.contains("webweaver bow");
	}

	private static boolean isArrow(String ammo)
	{
		return ammo.contains("arrow");
	}

	private static boolean isBolt(String ammo)
	{
		return ammo.contains("bolt");
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.toLowerCase(Locale.ROOT);
	}
}

package com.combatinsight.live;

import net.runelite.api.Actor;
import net.runelite.api.NPC;

/**
 * Retains the last NPC explicitly confirmed by an offensive player action.
 *
 * <p>The live actor is used only while combat is active. Its ID and name remain
 * available after death or despawn so hit chance and DPS can stay visible
 * between repeated kills without retaining a removed RuneLite actor.</p>
 */
public final class LiveTargetTracker
{
	private NPC activeTarget;
	private int retainedTargetId = -1;
	private String retainedTargetName = "";

	/**
	 * Confirms an NPC from an Attack/Cast click or a local-player hitsplat.
	 * Ordinary NPC interactions must never call this method.
	 */
	public boolean confirmCombatTarget(NPC target)
	{
		if (target == null)
		{
			return false;
		}

		int targetId = target.getId();
		String targetName = target.getName();
		boolean changed = activeTarget != target
			|| retainedTargetId != targetId
			|| !sameText(retainedTargetName, targetName);
		activeTarget = target;
		retainedTargetId = targetId;
		retainedTargetName = targetName;
		return changed;
	}

	/**
	 * Ends the live engagement only when the supplied actor is the active NPC.
	 * The retained ID and name intentionally survive for between-kill display.
	 */
	public boolean endActiveIfSame(Actor actor)
	{
		if (actor != null && actor == activeTarget)
		{
			activeTarget = null;
			return true;
		}
		return false;
	}

	public boolean endActiveIfDead()
	{
		if (activeTarget != null && activeTarget.isDead())
		{
			activeTarget = null;
			return true;
		}
		return false;
	}

	public boolean isEngagedWith(Actor interacting)
	{
		return activeTarget != null
			&& interacting == activeTarget
			&& !activeTarget.isDead();
	}

	public void clear()
	{
		activeTarget = null;
		retainedTargetId = -1;
		retainedTargetName = "";
	}

	public int getRetainedTargetId()
	{
		return retainedTargetId;
	}

	public String getRetainedTargetName()
	{
		return retainedTargetName;
	}

	public NPC getActiveTarget()
	{
		return activeTarget;
	}

	private static boolean sameText(String first, String second)
	{
		return first == null ? second == null : first.equals(second);
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.AttackType;
import com.combatinsight.calculation.SpecialAttackWeapon;
import com.combatinsight.calculation.TargetProfile;

/** Mutable state for one live NPC actor. */
final class TargetEffectState
{
	static final int RECOVERY_INTERVAL_TICKS = 100;

	private int targetId;
	private int baseDefence;
	private int currentDefence;
	private int baseMagic;
	private int currentMagic;
	private int baseMagicDefence;
	private int currentMagicDefence;
	private int defenceFloor;
	private boolean demon;
	private int nextRecoveryTick = -1;
	private boolean estimatedDefenceRecovery;
	private boolean estimatedMagicRecovery;
	private boolean tektonDefenceSpecialAttempted;

	TargetEffectState(TargetProfile target)
	{
		rebase(target);
	}

	void rebase(TargetProfile target)
	{
		if (target == null || target.isAmbiguous())
		{
			return;
		}

		int previousDefenceDrain = Math.max(0, baseDefence - currentDefence);
		int previousMagicDrain = Math.max(0, baseMagic - currentMagic);
		int previousMagicDefenceDrain = Math.max(0, baseMagicDefence - currentMagicDefence);
		targetId = target.getId();
		baseDefence = Math.max(0, target.getDefenceLevel());
		baseMagic = Math.max(0, target.getMagicLevel());
		baseMagicDefence = target.defenceBonus(AttackType.MAGIC);
		defenceFloor = Math.min(baseDefence, Math.max(0, TargetEffectRules.defenceFloor(target)));
		demon = target.hasAttribute("demon");
		currentDefence = Math.max(defenceFloor, baseDefence - previousDefenceDrain);
		currentMagic = Math.max(0, baseMagic - previousMagicDrain);
		currentMagicDefence = baseMagicDefence > 0
			? Math.max(0, baseMagicDefence - previousMagicDefenceDrain)
			: baseMagicDefence;
	}

	boolean apply(
		SpecialAttackWeapon weapon,
		int displayedDamage,
		String targetName,
		int gameTick)
	{
		return apply(weapon, displayedDamage, displayedDamage > 0, targetName, gameTick);
	}

	boolean apply(
		SpecialAttackWeapon weapon,
		int displayedDamage,
		boolean accurate,
		String targetName,
		int gameTick)
	{
		advance(gameTick);
		if (weapon == null || !weapon.hasTrackedTargetEffect())
		{
			return false;
		}

		int beforeDefence = currentDefence;
		int beforeMagic = currentMagic;
		int beforeMagicDefence = currentMagicDefence;
		boolean tekton = TargetEffectRules.isTekton(targetId, targetName);
		if (tekton)
		{
			tektonDefenceSpecialAttempted = true;
		}

		switch (weapon)
		{
			case DRAGON_WARHAMMER:
				if (accurate)
				{
					reduceDefence(currentDefence * 30 / 100);
				}
				else if (tekton)
				{
					reduceDefence(currentDefence * 5 / 100);
				}
				break;
			case ELDER_MAUL:
				if (accurate)
				{
					reduceDefence(currentDefence * 35 / 100);
				}
				else if (tekton)
				{
					reduceDefence(currentDefence * 5 / 100);
				}
				break;
			case BANDOS_GODSWORD:
				int drain = displayedDamage > 0 ? displayedDamage : tekton ? 10 : 0;
				reduceDefence(drain);
				break;
			case TONALZTICS_OF_RALOS:
				if (accurate)
				{
					reduceDefence(currentMagic / 8);
				}
				break;
			case EYE_OF_AYAK:
				if (displayedDamage > 0 && currentMagicDefence > 0)
				{
					currentMagicDefence = Math.max(0, currentMagicDefence - displayedDamage);
				}
				break;
			case ACCURSED_SCEPTRE:
				if (accurate)
				{
					int defenceLimit = Math.max(defenceFloor, baseDefence - baseDefence * 15 / 100);
					int magicLimit = Math.max(0, baseMagic - baseMagic * 15 / 100);
					currentDefence = Math.min(currentDefence, defenceLimit);
					currentMagic = Math.min(currentMagic, magicLimit);
				}
				break;
			case BONE_DAGGER:
				if (displayedDamage > 0 && currentDefence == baseDefence)
				{
					reduceDefence(displayedDamage);
				}
				break;
			case ARCLIGHT:
				if (accurate)
				{
					reduceDefence(baseDefence * (demon ? 10 : 5) / 100 + (demon ? 2 : 1));
				}
				break;
			case EMBERLIGHT:
				if (accurate)
				{
					reduceDefence(baseDefence * (demon ? 15 : 5) / 100 + 1);
				}
				break;
			case SEERCULL:
				if (displayedDamage > 0 && currentMagic == baseMagic)
				{
					currentMagic = Math.max(0, currentMagic - displayedDamage);
				}
				break;
			default:
				break;
		}

		boolean recoverableChanged = currentDefence != beforeDefence || currentMagic != beforeMagic;
		boolean changed = recoverableChanged || currentMagicDefence != beforeMagicDefence;
		if (recoverableChanged && nextRecoveryTick < 0)
		{
			nextRecoveryTick = gameTick + RECOVERY_INTERVAL_TICKS;
		}
		return changed || tekton;
	}

	void advance(int gameTick)
	{
		while (nextRecoveryTick >= 0 && gameTick >= nextRecoveryTick)
		{
			if (currentDefence < baseDefence)
			{
				currentDefence++;
				estimatedDefenceRecovery = true;
			}
			if (currentMagic < baseMagic)
			{
				currentMagic++;
				estimatedMagicRecovery = true;
			}
			if (currentDefence >= baseDefence && currentMagic >= baseMagic)
			{
				nextRecoveryTick = -1;
			}
			else
			{
				nextRecoveryTick += RECOVERY_INTERVAL_TICKS;
			}
		}
	}

	TargetEffectSnapshot snapshot()
	{
		boolean tracked = currentDefence != baseDefence
			|| currentMagic != baseMagic
			|| currentMagicDefence != baseMagicDefence;
		return new TargetEffectSnapshot(
			targetId,
			baseDefence,
			currentDefence,
			baseMagic,
			currentMagic,
			baseMagicDefence,
			currentMagicDefence,
			tracked,
			estimatedDefenceRecovery && currentDefence != baseDefence,
			estimatedMagicRecovery && currentMagic != baseMagic,
			tektonDefenceSpecialAttempted);
	}

	private void reduceDefence(int amount)
	{
		currentDefence = Math.max(defenceFloor, currentDefence - Math.max(0, amount));
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.TargetProfile;
import java.util.Objects;

/** Immutable raid inputs. Apply to bundled base stats before any local stat drains. */
public final class RaidScaling
{
	public static final RaidScaling DEFAULT = new RaidScaling(1, false, 126, 99, 99, 5);
	private final int coxSize;
	private final boolean challengeMode;
	private final int highestCombat;
	private final int highestHitpoints;
	private final int averageMining;
	private final int tobSize;

	public RaidScaling(int coxSize, boolean challengeMode, int highestCombat,
		int highestHitpoints, int averageMining, int tobSize)
	{
		this.coxSize = clamp(coxSize, 1, 100);
		this.challengeMode = challengeMode;
		this.highestCombat = clamp(highestCombat, 60, 126);
		this.highestHitpoints = clamp(highestHitpoints, 1, 99);
		this.averageMining = clamp(averageMining, 1, 99);
		this.tobSize = clamp(tobSize, 1, 5);
	}

	public TargetProfile apply(TargetProfile base)
	{
		if (base == null || base.isAmbiguous()) return base;
		if (base.hasAttribute("xerician")) return chambers(base);
		if (!base.hasAttribute("theatre_of_blood")) return base;
		int hp = base.getHitpoints();
		if (isEntryMode(base.getId()))
		{
			int[] fortieths = {0, 10, 19, 27, 34, 40};
			hp = hp * fortieths[tobSize] / 40;
		}
		else hp = hp * (Math.max(3, tobSize) + 3) / 8;
		return base.withRaidStats(base.getDefenceLevel(), base.getMagicLevel(),
			base.getHitpoints() == 0 ? 0 : Math.max(1, hp));
	}

	private TargetProfile chambers(TargetProfile base)
	{
		int id = base.getId();
		boolean cm = challengeMode || base.hasAttribute("cox_cm");
		boolean single = id == 7548 || id == 7549 || id == 7538 || id == 7539;
		boolean hand = id == 7550 || id == 7552 || id == 7553 || id == 7555;
		boolean mageHand = id == 7550 || id == 7553;
		boolean head = id == 7551 || id == 7554;
		boolean tekton = id >= 7540 && id <= 7545;
		boolean magicDefensive = hand || tekton || id == 7559 || id == 7533
			|| id >= 7530 && id <= 7532 || id == 7538 || id == 7539;
		int def = base.getDefenceLevel();
		// Both claws use the same linked defensive stat; mage claw is halved last.
		int magic = hand ? def : base.getMagicLevel();
		int hp = TargetMechanics.isGuardian(id) ? 151 + averageMining : base.getHitpoints();
		if (single)
		{
			int statPercent = Math.max(55, highestHitpoints);
			int combatPercent = highestCombat;
			if (cm)
			{
				statPercent += statPercent / 2;
				combatPercent += combatPercent / 2;
			}
			def = def == 1 ? 1 : Math.max(1, def * statPercent / 99);
			magic = magic == 1 ? 1 : Math.max(1, magic * statPercent / 99);
			hp = Math.max(5, hp * combatPercent / 126);
		}
		else
		{
			int membersBeyondSolo = coxSize - 1;
			int root = (int) Math.sqrt(membersBeyondSolo);
			int levelPercent = 55 + 44 * highestHitpoints / 99;
			int defensivePercent = 100 + root + membersBeyondSolo * 7 / 10;
			int offensivePercent = 100 + root * 7 + membersBeyondSolo;
			int cmDefencePercent = !cm || id == 7568 ? 100 : tekton ? (coxSize < 4 ? 120 : 135) : 150;
			def = scaledSkill(def, levelPercent, defensivePercent, cmDefencePercent, 20000);
			magic = scaledSkill(magic, levelPercent,
				magicDefensive ? defensivePercent : offensivePercent,
				magicDefensive ? cmDefencePercent : cm ? 150 : 100,
				magicDefensive ? 20000 : 5000);
			hp = hp * highestCombat / 126;
			hp *= 1 + coxSize / 2;
			if (cm && id != 7568) hp += hp / 2;
			hp = clamp(hp, 50, 30000);
		}
		if (hand || head)
		{
			int extra = Math.min(coxSize - 1, 50) - 3 * (Math.min(coxSize, 50) / 8);
			hp = hand ? 600 + 300 * extra : 800 + 400 * extra;
			if (mageHand) magic /= 2;
		}
		return base.withRaidStats(def, magic, hp);
	}

	private static int scaledSkill(int base, int levels, int party, int mode, int ceiling)
	{
		if (base == 1) return 1;
		return clamp(base * levels / 99 * party / 100 * mode / 100, 50, ceiling);
	}

	static boolean isEntryMode(int id)
	{
		return id == 10767 || id == 10768 || id >= 10774 && id <= 10789 || id == 10812
			|| id >= 10814 && id <= 10821 || id >= 10830 && id <= 10845
			|| id == 10864 || id == 10865;
	}

	public String notice(TargetProfile target)
	{
		if (target == null) return "";
		if (target.hasAttribute("xerician"))
			return "CoX input: " + coxSize + " players, "
				+ (challengeMode || target.hasAttribute("cox_cm") ? "CM" : "Normal")
				+ "; team stats " + highestCombat + " CB / " + highestHitpoints + " HP";
		if (target.hasAttribute("theatre_of_blood")) return "ToB input: " + tobSize + " players; local drains only";
		return "";
	}

	@Override public boolean equals(Object other)
	{
		if (!(other instanceof RaidScaling)) return false;
		RaidScaling that = (RaidScaling) other;
		return coxSize == that.coxSize && challengeMode == that.challengeMode
			&& highestCombat == that.highestCombat && highestHitpoints == that.highestHitpoints
			&& averageMining == that.averageMining && tobSize == that.tobSize;
	}

	@Override public int hashCode()
	{
		return Objects.hash(coxSize, challengeMode, highestCombat, highestHitpoints, averageMining, tobSize);
	}

	private static int clamp(int value, int min, int max) { return Math.max(min, Math.min(max, value)); }
}

package com.combatinsight.live;

import com.combatinsight.calculation.SpecialAttackWeapon;
import com.combatinsight.calculation.TargetProfile;
import java.util.IdentityHashMap;
import java.util.Map;
import net.runelite.api.NPC;

/** Keeps independent locally observed effects for each live NPC actor. */
final class TargetEffectTracker
{
	private final Map<NPC, TargetEffectState> states = new IdentityHashMap<>();
	private RaidScaling raidScaling = RaidScaling.DEFAULT;

	void setRaidScaling(RaidScaling next)
	{
		if (!raidScaling.equals(next))
		{
			states.clear();
			raidScaling = next;
		}
	}

	boolean record(
		SpecialAttackWeapon weapon,
		NPC target,
		int displayedDamage,
		boolean accurate,
		int gameTick)
	{
		if (weapon == null || !weapon.hasTrackedTargetEffect() || target == null)
		{
			return false;
		}

		TargetProfile baseTarget = raidScaling.apply(TargetDatabase.find(target.getId()));
		if (baseTarget == null || baseTarget.isAmbiguous())
		{
			return false;
		}

		TargetEffectState state = states.get(target);
		if (state == null)
		{
			state = new TargetEffectState(baseTarget);
			states.put(target, state);
		}
		else
		{
			state.rebase(baseTarget);
		}
		return state.apply(
			weapon,
			Math.max(0, displayedDamage),
			accurate,
			target.getName(),
			gameTick);
	}

	TargetEffectSnapshot snapshot(NPC target, int gameTick)
	{
		if (target == null)
		{
			return TargetEffectSnapshot.empty();
		}

		TargetProfile baseTarget = raidScaling.apply(TargetDatabase.find(target.getId()));
		if (baseTarget == null || baseTarget.isAmbiguous())
		{
			return TargetEffectSnapshot.empty();
		}

		TargetEffectState state = states.get(target);
		if (state == null)
		{
			return TargetEffectSnapshot.unmodified(baseTarget);
		}
		state.rebase(baseTarget);
		state.advance(gameTick);
		return state.snapshot();
	}

	void remove(NPC target)
	{
		if (target != null)
		{
			states.remove(target);
		}
	}

	void clear()
	{
		states.clear();
	}
}

package com.combatinsight.live;

import com.combatinsight.calculation.AttackType;

/** Explicitly withhold damage for encounter transforms not yet modelled. */
final class RaidDamageRules
{
	private RaidDamageRules() { }

	static String unavailableReason(int id, AttackType type, boolean fireSpell)
	{
		if (id >= 8369 && id <= 8371 || id >= 10830 && id <= 10832
			|| id >= 10847 && id <= 10849) return "Verzik P1 damage pending";
		if (TargetMechanics.isGuardian(id)) return "Guardian damage pending";
		if (id >= 7540 && id <= 7545 && type == AttackType.MAGIC)
			return "Tekton magic reduction pending";
		if (id == 7568 && type == AttackType.MAGIC) return "Crystal damage reduction pending";
		if ((id == 7551 || id == 7552 || id == 7554 || id == 7555) && type == AttackType.MAGIC)
			return "Olm damage reduction pending";
		if ((id == 7550 || id == 7552 || id == 7553 || id == 7555) && type.isRanged())
			return "Olm damage reduction pending";
		if ((id == 7584 || id == 7585) && !fireSpell) return "Ice demon damage pending";
		return "";
	}
}

